<?php use App\Core\CSRF; ?>
<div class="sports-head"><div><span class="sports-kicker">JOGAR</span><h1>Rachas</h1><p>Crie jogos, limite vagas e compartilhe um link para os jogadores confirmarem participação.</p></div></div>
<div class="row g-4"><div class="col-xl-4"><form class="card border-0 shadow-sm" method="post" action="/sports/games"><div class="card-body"><?=CSRF::field()?><h2 class="h5">Novo racha</h2><input class="form-control mb-2" name="name" required placeholder="Pelada dos Amigos"><label class="form-label">Quadra</label><select class="form-select mb-2" name="court_id" required><?php foreach($courts as $c):?><option value="<?=(int)$c['id']?>"><?=htmlspecialchars($c['name'])?></option><?php endforeach;?></select><label class="form-label">Modalidade</label><select class="form-select mb-2" name="modality_id" required><?php foreach($modalities as $m):?><option value="<?=(int)$m['id']?>"><?=htmlspecialchars($m['name'])?></option><?php endforeach;?></select><label class="form-label">Data/Hora</label><input class="form-control mb-2" type="datetime-local" name="starts_at" required><div class="row g-2"><div class="col-6"><label class="form-label">Duração</label><input class="form-control" type="number" name="duration_minutes" value="120" step="15"></div><div class="col-6"><label class="form-label">Valor total</label><input class="form-control" name="total_amount" required></div><div class="col-6"><label class="form-label">Vagas</label><input class="form-control" type="number" name="max_players" value="12" min="2"></div><div class="col-6"><label class="form-label">Mínimo</label><input class="form-control" type="number" name="minimum_players" value="12" min="1"></div></div><label class="form-check my-3"><input class="form-check-input" type="checkbox" name="split_payment" checked> Dividir valor entre jogadores</label><textarea class="form-control mb-2" name="rules" placeholder="Regras do jogo"></textarea><button class="btn btn-primary w-100">Criar racha e reservar quadra</button></div></form></div>
<div class="col-xl-8"><div class="sports-grid arena-game-grid"><?php foreach($games as $g):?><article class="sports-court-card"><div class="p-3"><span class="sports-status status-<?=htmlspecialchars($g['status'])?>"><?=htmlspecialchars($g['status'])?></span><h2 class="h5 mt-2"><?=htmlspecialchars($g['name'])?></h2><p><?=htmlspecialchars($g['court_name'])?> · <?=htmlspecialchars($g['modality_name']??'')?> · <?=date('d/m/Y H:i',strtotime($g['starts_at']))?></p><div class="arena-mini-kpis"><span><strong><?=(int)$g['confirmed_players']?>/<?=(int)$g['max_players']?></strong><small>confirmados</small></span><span><strong><?=(int)$g['paid_players']?></strong><small>pagos</small></span><span><strong>R$ <?=number_format((float)$g['received_amount'],2,',','.')?></strong><small>recebido</small></span></div><label class="form-label mt-3">Link público</label><div class="input-group"><input class="form-control" readonly value="<?=htmlspecialchars('/jogo/'.$g['public_token'])?>"><a class="btn btn-outline-primary" href="/jogo/<?=htmlspecialchars($g['public_token'])?>" target="_blank">Abrir</a></div></div></article><?php endforeach;?></div><?php if(!$games):?><div class="sports-empty">Nenhum racha criado.</div><?php endif;?></div></div>
